def plan(params, tokens, peak_tflops=989, mfu=0.45, price=3.0):
    flops = 6*params*tokens
    hrs = flops/(peak_tflops*1e12*mfu)/3600
    return {"FLOPs": f"{flops:.2e}", "gpu_hours": f"{hrs:,.0f}",
            "cost": f"${hrs*price:,.0f}"}
